import numpy as np,json

def Rq(q):
 w,x,y,z=q
 return np.array([[1-2*(y*y+z*z),2*(x*y-z*w),2*(x*z+y*w)],[2*(x*y+z*w),1-2*(x*x+z*z),2*(y*z-x*w)],[2*(x*z-y*w),2*(y*z+x*w),1-2*(x*x+y*y)]])
def Tpose(pos,q):
 T=np.eye(4);T[:3,:3]=Rq(q);T[:3,3]=pos;return T
m0=json.load(open('/app/runs/000_initial/meta.json'));m=json.load(open('/app/runs/015_lower_near_carton/meta.json'))
E=np.eye(4);E[:3,:]=m0['cameras']['wrist_cam']['extrinsic_cv']; Twc0=np.linalg.inv(E)
p0=np.array(m0['proprio']['now'][8:11]);q0=np.array(m0['proprio']['now'][11:15]); T_ec=np.linalg.inv(Tpose(p0,q0))@Twc0
p=np.array(m['proprio']['now'][8:11]);q=np.array(m['proprio']['now'][11:15]); Twc=Tpose(p,q)@T_ec
print('cur p q',p,q,'T_wc',Twc)
K=np.array(m0['cameras']['wrist_cam']['intrinsic_cv']);
for world in [[.48,.003,.02],[.48,.003,.003],[.4817,.0017,.0658]]:
 pc=np.linalg.inv(Twc)@[*world,1];uv=K@pc[:3];print(world,pc[:3],uv[:2]/uv[2])
